import type AudioTrack from 'video.js/dist/types/tracks/audio-track'

/**
 * Minimal typings for the parts of shaka player and video.js that the plugin
 * touches. Shaka player ships its typings as a global namespace generated by
 * clutz, which is not usable as an import, so the plugin describes the shapes
 * it relies on here.
 */

export interface ShakaTrack {
  id: number
  active: boolean
  type: string
  bandwidth: number
  language: string
  label: string | null
  kind: string | null
  roles?: string[]
  audioRoles?: string[] | null
  forced?: boolean
  width: number | null
  height: number | null
  frameRate: number | null
  channelsCount: number | null
  audioId?: number | null
  codecs?: string
  videoCodec?: string | null
  audioCodec?: string | null
}

export interface ShakaRestrictions {
  minHeight?: number
  maxHeight?: number
  minWidth?: number
  maxWidth?: number
  minBandwidth?: number
  maxBandwidth?: number
  minFrameRate?: number
  maxFrameRate?: number
  minChannelsCount?: number
  maxChannelsCount?: number
  minPixels?: number
  maxPixels?: number
}

export interface ShakaAbrConfiguration {
  enabled?: boolean
  bandwidthUpgradeTarget?: number
  restrictions?: ShakaRestrictions
}

export interface ShakaCue {
  startTime: number
  endTime: number
  payload?: string
  lineBreak?: boolean
  nestedCues?: Partial<ShakaCue>[]
}

export interface ShakaError {
  code: number
  category?: number
  severity?: number
  message?: string
}

export interface ShakaTextDisplayer {
  configure(config: object): void
  append(cues: ShakaCue[]): void
  remove(startTime: number, endTime: number): boolean
  isTextVisible(): boolean
  setTextVisibility(on: boolean): void
  setTextLanguage(language: string): void
  destroy(): Promise<void>
}

export type ShakaTextDisplayFactory = (shakaPlayer?: ShakaPlayer) => ShakaTextDisplayer

export interface ShakaRequest {
  uris: string[]
  method: string
  headers: Record<string, string>
  body: ArrayBuffer | ArrayBufferView | null
}

export type ShakaRequestFilter = (type: number, request: ShakaRequest) => void | Promise<void>

export type ShakaDrmConfiguration = Record<string, unknown>

interface ShakaConfigurationBase {
  abr?: ShakaAbrConfiguration
  textDisplayFactory?: ShakaTextDisplayFactory
  [key: string]: unknown
}

/**
 * The shaka player configuration the plugin reads or writes. Anything else is
 * passed through to shaka player untouched.
 */
export interface ShakaConfiguration extends ShakaConfigurationBase {
  drm?: ShakaDrmConfiguration
}

/**
 * `ShakaConfiguration` as given in the tech options, where `drm` can also be
 * a function that returns the drm configuration.
 */
export interface ShakaTechConfiguration extends ShakaConfigurationBase {
  drm?: ShakaDrmConfiguration | (() => ShakaDrmConfiguration)
}

export interface ShakaTechOptions {
  playerId?: string
  debug?: boolean
  sideload?: boolean
  configuration?: ShakaTechConfiguration
  licenseServerAuth?: ShakaRequestFilter
}

export interface ShakaEvent {
  buffering?: boolean
  detail?: ShakaError
}

export interface ShakaPlayer {
  attach(element: HTMLMediaElement): Promise<void>
  configure(config: ShakaConfiguration | ShakaTechConfiguration): boolean
  getConfiguration(): ShakaConfiguration
  load(src: string, startTime?: number | null, mimeType?: string | null): Promise<void>
  unload(): Promise<void>
  destroy(): Promise<void>
  addEventListener(type: string, listener: (event: ShakaEvent) => void): void
  getNetworkingEngine(): {registerRequestFilter(filter: ShakaRequestFilter): void}
  getVariantTracks(): ShakaTrack[]
  getAudioTracks(): ShakaTrack[]
  getTextTracks(): ShakaTrack[]
  getStats(): {estimatedBandwidth: number}
  selectVariantTrack(track: ShakaTrack, clearBuffer?: boolean): void
  selectAudioTrack(track: ShakaTrack): void
  selectTextTrack(track: ShakaTrack | null): void
  // removed in shaka player 5
  setTextTrackVisibility?(visible: boolean): void
}

export interface ShakaErrorStatic {
  new (severity: number, category: number, code: number, ...args: Array<string | number>): ShakaError
  Severity: {RECOVERABLE: number; CRITICAL: number}
  Category: {NETWORK: number}
  Code: {BAD_HTTP_STATUS: number}
}

export interface ShakaNamespace {
  Player: {new (): ShakaPlayer; prototype: ShakaPlayer; isBrowserSupported(): boolean}
  polyfill: {installAll(): void}
  log?: {setLevel(level: number): void; Level: {DEBUG: number; ERROR: number}}
  util?: {Error?: ShakaErrorStatic}
}

export interface QualityEntry {
  id: number
  label: string
  height?: number
  bandwidth?: number
  selected: boolean
}

export type QualitySwitchCallback = (id: number, type: string) => void

export interface QualityData {
  video?: QualityEntry[]
  audio?: QualityEntry[]
  subtitle?: QualityEntry[]
}

export type VjsAudioTrack = AudioTrack & {id: string}

export interface ShakaTextTrackEntry {
  textTrack: TextTrack
  shakaTrack: ShakaTrack
}
